using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class AuditSector {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static string O=>R+"/Docs/검수/2026-11-06_B5_Sector01/";
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("Sector01_CompletedArt");Physics.SyncTransforms();
 var floor=JObject.Parse(File.ReadAllText(R+"/Docs/도면/Decision/원형공동/facility_layout.json"))["floors"].Single(f=>(string)f["id"]=="B5");var blocks=new List<object>();int samples=0;
 foreach(string key in new[]{"route","alternate"}){var ps=floor[key].ToArray();for(int i=1;i<ps.Length;i++){var a=new Vector3((float)ps[i-1][0],-82,-(float)ps[i-1][1]);var b=new Vector3((float)ps[i][0],-82,-(float)ps[i][1]);int n=Math.Max(1,Mathf.CeilToInt(Vector3.Distance(a,b)/.25f));for(int j=0;j<=n;j++){var p=Vector3.Lerp(a,b,(float)j/n);samples++;var hits=Physics.OverlapCapsule(p+Vector3.up*.34f,p+Vector3.up*1.48f,.28f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).ToArray();if(hits.Length>0)blocks.Add(new{key,p=p.ToString(),hits=hits.Select(c=>PathOf(c.transform)).Distinct().ToArray()});}}}
 var missing=root.GetComponentsInChildren<MeshFilter>().Where(f=>!f.sharedMesh).Select(f=>f.name).ToArray();var matMissing=group.GetComponentsInChildren<Renderer>().Where(r=>r.sharedMaterials.Any(m=>!m||!m.shader||m.shader.name=="Hidden/InternalErrorShader")).Select(r=>r.name).ToArray();
 var items=group.Cast<Transform>().Select(t=>new{name=t.name,position=t.localPosition.ToString(),rotation=t.localEulerAngles.ToString(),bounds=t.GetComponentsInChildren<Renderer>().Where(x=>!x.name.Contains("_LOD")||x.name.EndsWith("_LOD0")).Select(r=>new{r.name,center=r.bounds.center.ToString(),size=r.bounds.size.ToString(),mesh=r.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh):""}).ToArray(),colliders=t.GetComponentsInChildren<Collider>().Select(c=>new{c.name,type=c.GetType().Name,center=c.bounds.center.ToString(),size=c.bounds.size.ToString()}).ToArray()}).ToArray();
 var lights=root.GetComponentsInChildren<Light>().Where(l=>l.name.StartsWith("C01")||l.transform.IsChildOf(group)).Select(l=>new{path=PathOf(l.transform),type=l.type.ToString(),l.enabled,l.intensity,l.range,pos=l.transform.position.ToString(),forward=l.transform.forward.ToString()}).ToArray();
 var bps=group.GetComponentsInChildren<BoxCollider>();var overlaps=new List<object>();foreach(var box in bps)foreach(var c in Physics.OverlapBox(box.bounds.center,box.bounds.extents,Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=box&&!c.transform.IsChildOf(box.transform)&&c.transform.IsChildOf(root)&&!c.name.Contains("Floor"))){Vector3 dir;float depth;if(Physics.ComputePenetration(box,box.transform.position,box.transform.rotation,c,c.transform.position,c.transform.rotation,out dir,out depth)&&depth>.035f)overlaps.Add(new{box=PathOf(box.transform),other=PathOf(c.transform),depth});}
 var lods=group.GetComponentsInChildren<LODGroup>().Select(l=>new{l.name,levels=l.GetLODs().Select(x=>x.renderers.Length).ToArray()}).ToArray();
 var result=new{scene=s.path,routeSamples=samples,blocks,overlaps,missing,matMissing,items,lights,lods,trianglesLod0=group.GetComponentsInChildren<MeshFilter>().Where(f=>!f.name.Contains("_LOD")||f.name.EndsWith("_LOD0")).Sum(f=>f.sharedMesh.triangles.Length/3),pipeline=UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline?UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline.name:"none",pixelLightCount=QualitySettings.pixelLightCount};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{samples,blocked=blocks.Count,overlaps,missing,matMissing,lights,lods,result.trianglesLod0};}
}
